  white-space:nowrap; overflow:hidden;
}#stage .sk-code-b{ flex:1; min-height:0; padding:14px 0; display:flex; flex-direction:column; }#stage .sk-ln{
  height:52px; flex-shrink:0; display:block;
  padding:0 26px; border-left:4px solid transparent;
  font-family:var(--font-mono); font-size:27px; font-weight:600; line-height:52px;
  white-space:pre; overflow:hidden; color:var(--code-plain);
