var SK = window.__SK || (window.__SK = {});

SK.pill = function(i, value, unit, tone){
  MSD.q('#sk-pill-v-' + i).textContent = value;
  if(unit !== null) MSD.qa('#sk-pill-' + i + ' .sk-pill-u')[0].textContent = unit;
  MSD.cls('#sk-pill-' + i, 'bad', tone === 'bad');
  MSD.cls('#sk-pill-' + i, 'good', tone === 'good');
};

// Which nodes exist, and which one is lit this stage.
SK.nodes = function(list, live){
  ['app','api','cloud','atk','vault'].forEach(function(n){
    MSD.cls('#sk-n-' + n, 'on', list.indexOf(n) !== -1);
    MSD.cls('#sk-n-' + n, 'live', (live || []).indexOf(n) !== -1);
  });
};

// Wires: on = drawn, flow = dots moving, tone = colour.
SK.wire = function(id, state, tone){
  var el = '#sk-w-' + id;
  MSD.cls(el, 'on', state !== 'off');
  MSD.cls(el, 'flow', state === 'flow');
  MSD.cls(el, 'dead', state === 'dead');
  MSD.cls(el, 'hot', tone === 'hot');
  MSD.cls(el, 'bad', tone === 'bad');
};
SK.wires = function(map){
  ['direct','a1','a2','atk','vault'].forEach(function(id){
    var v = map[id] || ['off', ''];
    SK.wire(id, v[0], v[1]);
  });
};

SK.cnt = function(node, value){
  var el = '#sk-c-' + node;
  MSD.cls(el, 'on', value !== null);
  if(value !== null) MSD.q(el).textContent = value;
};

// The code block. lines is an array of HTML strings; active is 1-based.
SK.code = function(file, lines, active, gone, tone){
  MSD.q('#sk-code-h').textContent = file;
  for(var i = 1; i <= 5; i++){
    var el = MSD.q('#sk-ln-' + i);
    el.innerHTML = lines[i - 1] || '';
    MSD.cls('#sk-ln-' + i, 'active', i === active);
    MSD.cls('#sk-ln-' + i, 'gone', (gone || []).indexOf(i) !== -1);
  }
  MSD.cls('#sk-code', 'bad', tone === 'bad');
  MSD.cls('#sk-code', 'good', tone === 'good');
};

SK.BEFORE = [
  '<span class="c">// runs on the phone</span>',
  '<span class="k">var</span> key = <span class="s">"sk-live-7f3a91c4"</span>;',
  '<span class="k">var</span> ai = <span class="k">new</span> <span class="f">AzureOpenAIClient</span>(',
  '&nbsp;&nbsp;&nbsp;&nbsp;uri, <span class="k">new</span> <span class="f">ApiKeyCredential</span>(key));',
  ''
];

SK.AFTER = [
  '<span class="c">// runs in your API, never shipped</span>',
  'builder.Configuration.<span class="f">AddAzureKeyVault</span>(',
  '&nbsp;&nbsp;&nbsp;&nbsp;vaultUri, <span class="k">new</span> <span class="f">DefaultAzureCredential</span>());',
  '',
  '<span class="c">// the phone gets a token, never a key</span>'
];

/* ------------------------------------------- opening state -------- */
MSD.cls('#sk-map', 'dim', false);
MSD.cls('#sk-payoff', 'on', false);
MSD.cls('#sk-cut', 'on', false);

SK.pill(1, '1', 'key', '');
SK.pill(2, '0', '', '');
SK.nodes(['app', 'cloud'], []);
SK.wires({ direct: ['on', ''] });
SK.cnt('app', null); SK.cnt('api', null); SK.cnt('atk', null); SK.cnt('vault', null);
SK.cnt('cloud', '0');
SK.code('MauiProgram.cs · ships inside the app', SK.BEFORE, 2, [], '');

MSD.after(400, function(){
  SK.wires({ direct: ['flow', 'hot'] });
  SK.nodes(['app', 'cloud'], ['app']);
  MSD.sfx.whoosh();
});
MSD.after(1100, function(){
  MSD.count('#sk-c-cloud', 24, 1400);
  MSD.sfx.data(0);
});
MSD.after(2000, function(){ MSD.punch('#sk-ln-2', 3); });

var SK = window.__SK;

SK.pill(1, '1', 'key', '');
SK.pill(2, '0', '', '');
SK.nodes(['app', 'cloud', 'atk'], ['atk']);
SK.wires({ direct: ['flow', 'hot'] });
SK.cnt('cloud', '24');
SK.code('MauiProgram.cs · ships inside the app', SK.BEFORE, 2, [], '');

MSD.after(300, function(){
